//! Shared engine: one long-lived micro-VM running `docker:dind`.
//!
//! The engine is an ordinary container flagged `engine` (the guest init loads
//! bridge/netfilter modules, enables forwarding and, with a GPU, writes the
//! `veynodevm.dev/gpu` CDI spec). dockerd's TLS endpoint (mutual TLS, client
//! certificates generated by dind into a host-shared directory) is published
//! on host loopback, and a `veynodevm` docker context points at it, so the
//! stock docker CLI and compose work unchanged. Directories given with
//! `--share` are mounted at the same path, so host bind mounts under them work.
use crate::container::{self, RunOptions};
use anyhow::{bail, Context, Result};
use std::{
    path::PathBuf,
    process::Command,
    time::{Duration, Instant},
};
use vm_control::home;

pub const NAME: &str = "veynodevm-engine";
pub const IMAGE: &str = "docker:28-dind";
pub const CONTEXT: &str = "veynodevm";
const DEFAULT_PORT: u16 = 2376;

fn certs() -> Result<PathBuf> {
    let dir = home::private_dir(&home::root()?.join("engine"))?;
    Ok(dir.join("certs"))
}

fn port(c: &container::Container) -> u16 {
    c.ports.first().map(|p| p.host_port).unwrap_or(DEFAULT_PORT)
}

fn docker_cli() -> Option<PathBuf> {
    veynodevm_oci::store::which("docker")
}

/// Environment for the docker CLI to reach the engine directly.
pub fn env() -> Result<Vec<(String, String)>> {
    let c = container::find(NAME).context("engine not created; run veynodevm engine start")?;
    Ok(vec![
        (
            "DOCKER_HOST".into(),
            format!("tcp://127.0.0.1:{}", port(&c)),
        ),
        ("DOCKER_TLS_VERIFY".into(), "1".into()),
        (
            "DOCKER_CERT_PATH".into(),
            certs()?.to_string_lossy().into_owned(),
        ),
    ])
}

fn wait_ready(c: &container::Container, timeout: Duration) -> Result<()> {
    let deadline = Instant::now() + timeout;
    let cert = certs()?.join("cert.pem");
    loop {
        let console = container::read_console(c);
        if let Some(code) = console.exit {
            bail!("engine exited with status {code}; see veynodevm logs {NAME}")
        }
        if cert.exists() && std::net::TcpStream::connect(("127.0.0.1", port(c))).is_ok() {
            match docker_cli() {
                None => return Ok(()),
                Some(docker) => {
                    let ok = Command::new(docker)
                        .args(["version", "--format", "{{.Server.Version}}"])
                        .envs(env()?)
                        .output()
                        .map(|o| o.status.success())
                        .unwrap_or(false);
                    if ok {
                        return Ok(());
                    }
                }
            }
        }
        if Instant::now() > deadline {
            bail!("engine did not become ready in time; see veynodevm logs {NAME}")
        }
        std::thread::sleep(Duration::from_millis(500));
    }
}

/// Create or refresh the `veynodevm` docker context (additive; never switches
/// the current context).
fn ensure_context(c: &container::Container) -> Result<Option<String>> {
    let Some(docker) = docker_cli() else {
        return Ok(None);
    };
    let certs = certs()?;
    let endpoint = format!(
        "host=tcp://127.0.0.1:{},ca={},cert={},key={}",
        port(c),
        certs.join("ca.pem").display(),
        certs.join("cert.pem").display(),
        certs.join("key.pem").display()
    );
    let exists = Command::new(&docker)
        .args(["context", "inspect", CONTEXT])
        .output()?
        .status
        .success();
    let action = if exists { "update" } else { "create" };
    let output = Command::new(&docker)
        .args([
            "context",
            action,
            CONTEXT,
            "--description",
            "VeynodeVM shared engine",
            "--docker",
            &endpoint,
        ])
        .output()?;
    if !output.status.success() {
        bail!(
            "docker context {action} failed: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        )
    }
    Ok(Some(CONTEXT.into()))
}

/// A host directory shared into the engine at the same path.
fn shared_dir(dir: &str) -> Result<PathBuf> {
    let path = std::fs::canonicalize(dir).with_context(|| format!("--share {dir}"))?;
    if !path.is_dir() || path == std::path::Path::new("/") {
        bail!("--share needs an existing directory other than /: {dir}")
    }
    if path
        .to_str()
        .is_none_or(|p| p.contains(':') || p.contains(','))
    {
        bail!("--share path must be UTF-8 without ':' or ','")
    }
    Ok(path)
}

fn start(rest: &[String]) -> Result<i32> {
    let p = crate::args::parse(
        rest,
        &[
            ("gpus", None, true),
            ("cpus", None, true),
            ("memory", Some('m'), true),
            ("disk-size", None, true),
            ("port", None, true),
            ("image", None, true),
            ("dns", None, true),
            ("mtu", None, true),
            ("share", None, true),
        ],
        false,
    )?;
    let shares = p
        .values("share")
        .iter()
        .map(|dir| shared_dir(dir))
        .collect::<Result<Vec<_>>>()?;
    let c = match container::find(NAME) {
        Ok(c) => {
            let (state, _) = container::status_text(&c);
            if !shares.is_empty() || p.value("gpus").is_some() {
                bail!("--share and --gpus apply when the engine is created; run `veynodevm rm -f {NAME}` first (its images and containers are discarded)")
            }
            if matches!(state.as_str(), "stopped" | "crashed" | "missing") {
                container::start(&c)?;
            }
            c
        }
        Err(_) => {
            let certs = certs()?;
            std::fs::create_dir_all(&certs)?;
            let port: u16 = p
                .value("port")
                .map(str::parse)
                .transpose()
                .context("invalid --port")?
                .unwrap_or(DEFAULT_PORT);
            // Inside the engine VM, inbound segments above ~1300 bytes were
            // observed to be lost on Apple NAT while plain containers were
            // unaffected (docs/known-issues.md); 1280 is the safe default.
            let mtu: u16 = p
                .value("mtu")
                .map(str::parse)
                .transpose()
                .context("invalid --mtu")?
                .unwrap_or(1280);
            eprintln!(
                "creating shared engine ({})",
                p.value("image").unwrap_or(IMAGE)
            );
            container::create_and_start(&RunOptions {
                image: p.value("image").unwrap_or(IMAGE).into(),
                name: Some(NAME.into()),
                detach: true,
                ports: vec![format!("127.0.0.1:{port}:2376")],
                // Shared host directories keep their path, so `docker run -v`
                // and compose bind mounts under them resolve inside the VM.
                volumes: std::iter::once(format!("{}:/certs/client", certs.display()))
                    .chain(shares.iter().map(|d| format!("{0}:{0}", d.display())))
                    .collect(),
                cpus: Some(
                    p.value("cpus")
                        .map(str::parse)
                        .transpose()
                        .context("invalid --cpus")?
                        .unwrap_or(4),
                ),
                memory_mib: Some(
                    p.value("memory")
                        .map(crate::args::memory_mib)
                        .transpose()?
                        .unwrap_or(4096),
                ),
                disk_gib: Some(
                    p.value("disk-size")
                        .map(|d| d.trim_end_matches(['g', 'G']).parse())
                        .transpose()
                        .context("invalid --disk-size")?
                        .unwrap_or(64),
                ),
                gpus: p.value("gpus").map(str::to_owned),
                engine: true,
                dns: p.values("dns").to_vec(),
                mtu: Some(mtu),
                // dind passes leading flags to dockerd; inner bridges match the VM.
                command: vec![format!("--mtu={mtu}")],
                ..Default::default()
            })?
        }
    };
    wait_ready(&c, Duration::from_secs(180))?;
    match ensure_context(&c)? {
        Some(context) => println!("engine ready: docker --context {context} ps"),
        None => println!(
            "engine ready at tcp://127.0.0.1:{} (docker CLI not found; see veynodevm engine env)",
            port(&c)
        ),
    }
    Ok(0)
}

pub fn command(rest: &[String], json_output: bool) -> Result<i32> {
    let action = rest.first().map(String::as_str).unwrap_or("status");
    let tail = rest.get(1..).unwrap_or(&[]);
    match action {
        "start" => start(tail),
        "stop" => {
            container::stop(&container::find(NAME)?, Duration::from_secs(20))?;
            println!("engine stopped");
            Ok(0)
        }
        "rm" => {
            container::remove(&container::find(NAME)?, tail.iter().any(|a| a == "-f"))?;
            println!(
                "engine removed (images and containers inside it are gone; certificates kept)"
            );
            Ok(0)
        }
        "env" => {
            for (k, v) in env()? {
                println!("export {k}={}", shell_quote(&v));
            }
            Ok(0)
        }
        "status" => {
            let Ok(c) = container::find(NAME) else {
                println!("engine not created (veynodevm engine start)");
                return Ok(1);
            };
            let (state, status) = container::status_text(&c);
            let console = container::read_console(&c);
            if json_output {
                println!(
                    "{}",
                    serde_json::json!({"state":state,"status":status,"endpoint":format!("tcp://127.0.0.1:{}",port(&c)),"context":CONTEXT,"gpu":console.gpu,"backend":c.backend})
                );
            } else {
                println!(
                    "{status}  endpoint tcp://127.0.0.1:{}  backend {}  gpu {}",
                    port(&c),
                    c.backend,
                    console.gpu.unwrap_or_else(|| "none".into())
                );
            }
            Ok(0)
        }
        other => bail!("unknown engine command: {other} (start, stop, status, env, rm)"),
    }
}

fn shell_quote(s: &str) -> String {
    format!("'{}'", s.replace('\'', "'\\''"))
}

/// `veynodevm run --shared ...` → `docker run ...` against the engine, with
/// `--gpus` mapped to the engine's CDI device. `spec` is the run flag table,
/// used to tell option values from the image name.
pub fn run_shared(rest: &[String], spec: &[(&str, Option<char>, bool)]) -> Result<i32> {
    let docker = docker_cli().context("--shared needs the docker CLI on PATH")?;
    let args = shared_args(rest, spec);
    let status = Command::new(docker).args(&args).envs(env()?).status()?;
    Ok(status.code().unwrap_or(125))
}

fn shared_args(rest: &[String], spec: &[(&str, Option<char>, bool)]) -> Vec<String> {
    let takes_value = |arg: &str| -> bool {
        if let Some(long) = arg.strip_prefix("--") {
            return !long.contains('=') && spec.iter().any(|(l, _, t)| *l == long && *t);
        }
        // Short group: a value-taking flag last with nothing after it.
        arg.strip_prefix('-')
            .and_then(|g| g.chars().last())
            .is_some_and(|c| spec.iter().any(|(_, s, t)| *s == Some(c) && *t))
            && arg.len() == 2
    };
    let mut args = vec!["run".to_owned()];
    let mut index = 0;
    while index < rest.len() {
        let arg = &rest[index];
        index += 1;
        if !arg.starts_with('-') || arg == "--" {
            args.extend(rest[index - 1..].iter().cloned());
            break;
        }
        if arg == "--shared" {
            continue;
        }
        if arg == "--gpus" || arg.starts_with("--gpus=") {
            if arg == "--gpus" {
                index += 1;
            }
            args.extend(["--device".into(), "veynodevm.dev/gpu=all".into()]);
            continue;
        }
        args.push(arg.clone());
        if takes_value(arg) && index < rest.len() {
            args.push(rest[index].clone());
            index += 1;
        }
    }
    args
}

/// `veynodevm build -t TAG [--file F] CONTEXT`: build with the engine's
/// BuildKit-capable dockerd, then import the result into the micro-VM image
/// store (`docker save` archive), so it runs with `veynodevm run`.
pub fn build(rest: &[String]) -> Result<i32> {
    let p = crate::args::parse(
        rest,
        &[
            ("tag", Some('t'), true),
            ("file", Some('f'), true),
            ("build-arg", None, true),
        ],
        false,
    )?;
    let tag = p.value("tag").context("build requires -t TAG")?;
    let context = p
        .positional
        .first()
        .context("build requires a CONTEXT directory")?;
    let docker = docker_cli().context("build needs the docker CLI on PATH")?;
    let env = env()?;
    let mut args = vec!["build".to_owned(), "-t".into(), tag.into()];
    if let Some(file) = p.value("file") {
        args.extend(["-f".into(), file.into()]);
    }
    for arg in p.values("build-arg") {
        args.extend(["--build-arg".into(), arg.clone()]);
    }
    args.push(context.clone());
    if !Command::new(&docker)
        .args(&args)
        .envs(env.clone())
        .status()?
        .success()
    {
        bail!("docker build failed")
    }
    let store = veynodevm_oci::Store::open(&home::images_dir()?)?;
    let archive = home::images_dir()?
        .join("tmp")
        .join(format!("build-{}.tar", crate::random_hex(8)));
    let saved = Command::new(&docker)
        .args(["save", "-o"])
        .arg(&archive)
        .arg(tag)
        .envs(env)
        .status()?;
    let loaded = if saved.success() {
        store.load(&archive)
    } else {
        Err(anyhow::anyhow!("docker save failed"))
    };
    let _ = std::fs::remove_file(&archive);
    for image in loaded? {
        let root = store.rootfs(&image, &mut |m| eprintln!("{m}"))?;
        println!("Loaded image: {} ({})", image.reference, root.display());
    }
    Ok(0)
}

#[cfg(test)]
mod tests {
    #[test]
    fn shared_translation() {
        let spec: &[(&str, Option<char>, bool)] = &[
            ("publish", Some('p'), true),
            ("gpus", None, true),
            ("shared", None, false),
            ("rm", None, false),
        ];
        let s = |v: &[&str]| v.iter().map(|s| s.to_string()).collect::<Vec<_>>();
        assert_eq!(
            super::shared_args(
                &s(&["--shared", "-p", "8080:80", "--gpus", "all", "--rm", "nginx", "--gpus"]),
                spec
            ),
            s(&[
                "run",
                "-p",
                "8080:80",
                "--device",
                "veynodevm.dev/gpu=all",
                "--rm",
                "nginx",
                "--gpus"
            ])
        );
    }
}
